local addonName, Private = ...
local L = Private.L
local merfinUI = Private.MerfinProfileName

local E = unpack(ElvUI)

local auras = {}

function Private.ImportWeakAuras(name)
  if not E:IsAddOnEnabled('WeakAuras') then
    Private:Print(string.format(L['You need to enable %s first.'], 'WeakAuras'))
    return
  end

  local auraName = name
  local importCode = ''

  if auraName == 'T13_ANCHORS' then
    local reso = Private.GetProfileResolution()
    auraName = reso == 'QUAD_HD' and 'T13_ANCHORS_QUAD' or 'T13_ANCHORS_FULL'
  end

  importCode = auras[auraName]

  WeakAuras.Import(importCode)
end

